#!/usr/bin/env node
/**
 * pdf-ocr-to-excel.mjs
 *
 * Usage:  node pdf-ocr-to-excel.mjs <input.pdf> [output.xlsx]
 *
 * 1. Renders the FIRST page of the PDF to a bitmap (via pdfjs-dist).
 * 2. Runs OCR on that bitmap with Tesseract.js.
 * 3. Writes the recognised text into an Excel file (one line per row).
 */

import { readFileSync } from "fs";
import { resolve } from "path";
import { getDocument } from "pdfjs-dist/legacy/build/pdf.mjs";
import { createWorker } from "tesseract.js";
import ExcelJS from "exceljs";

// ── Args ────────────────────────────────────────────────────────────
const pdfPath = process.argv[2];
const xlsxPath = process.argv[3] || pdfPath?.replace(/\.pdf$/i, "") + "_ocr.xlsx";

if (!pdfPath) {
  console.error("Usage: node pdf-ocr-to-excel.mjs <input.pdf> [output.xlsx]");
  process.exit(1);
}

// ── Step 1: Render the first PDF page to a raw pixel buffer ─────────
console.log(`📄 Loading PDF: ${pdfPath}`);
const data = new Uint8Array(readFileSync(resolve(pdfPath)));
const pdfDoc = await getDocument({ data, useSystemFonts: true }).promise;
const page = await pdfDoc.getPage(1); // first page

const scale = 2; // 2× for better OCR accuracy
const viewport = page.getViewport({ scale });
const width = Math.floor(viewport.width);
const height = Math.floor(viewport.height);

// Minimal canvas-like object that pdfjs can render into (no native canvas needed)
class NodeCanvasFactory {
  create(w, h) {
    const buf = new Uint8ClampedArray(w * h * 4); // RGBA
    return {
      canvas: { width: w, height: h },
      context: {
        _buf: buf,
        drawImage() {},
        putImageData(imgData, x, y) {
          // copy pixel data into our buffer
          for (let row = 0; row < imgData.height; row++) {
            const srcOff = row * imgData.width * 4;
            const dstOff = ((y + row) * w + x) * 4;
            buf.set(imgData.data.subarray(srcOff, srcOff + imgData.width * 4), dstOff);
          }
        },
        getImageData(x, y, w2, h2) {
          return { data: buf, width: w2, height: h2 };
        },
        // Stubs pdfjs may call:
        save() {}, restore() {}, transform() {}, setTransform() {},
        resetTransform() {}, clip() {}, moveTo() {}, lineTo() {},
        beginPath() {}, closePath() {}, stroke() {}, fill() {},
        rect() {}, fillRect(x, y, rw, rh) {
          // fill with current fillStyle (often white bg)
          const rgba = parseColor(this.fillStyle);
          for (let row = y; row < y + rh && row < h; row++) {
            for (let col = x; col < x + rw && col < w; col++) {
              const off = (row * w + col) * 4;
              buf[off] = rgba[0]; buf[off+1] = rgba[1]; buf[off+2] = rgba[2]; buf[off+3] = rgba[3];
            }
          }
        },
        strokeRect() {},
        translate() {}, rotate() {}, scale() {},
        arc() {}, arcTo() {}, ellipse() {}, bezierCurveTo() {},
        quadraticCurveTo() {}, createLinearGradient() {
          return { addColorStop() {} };
        },
        createRadialGradient() { return { addColorStop() {} }; },
        createPattern() { return {}; },
        measureText(t) { return { width: t.length * 5 }; },
        fillText() {}, strokeText() {},
        setLineDash() {}, getLineDash() { return []; },
        createImageData(w2, h2) { return { data: new Uint8ClampedArray(w2 * h2 * 4), width: w2, height: h2 }; },
        // Properties pdfjs sets:
        fillStyle: "#ffffff",
        strokeStyle: "#000000",
        lineWidth: 1,
        lineCap: "butt",
        lineJoin: "miter",
        miterLimit: 10,
        lineDashOffset: 0,
        font: "10px sans-serif",
        textAlign: "left",
        textBaseline: "alphabetic",
        globalAlpha: 1,
        globalCompositeOperation: "source-over",
        imageSmoothingEnabled: true,
      },
    };
  }
  reset(canvasAndCtx, w, h) {
    canvasAndCtx.canvas.width = w;
    canvasAndCtx.canvas.height = h;
  }
  destroy(canvasAndCtx) {}
}

function parseColor(css) {
  if (!css || css === "none") return [0, 0, 0, 0];
  if (css.startsWith("#")) {
    const hex = css.slice(1);
    if (hex.length === 3) return [parseInt(hex[0]+hex[0],16), parseInt(hex[1]+hex[1],16), parseInt(hex[2]+hex[2],16), 255];
    if (hex.length >= 6) return [parseInt(hex.slice(0,2),16), parseInt(hex.slice(2,4),16), parseInt(hex.slice(4,6),16), 255];
  }
  return [255, 255, 255, 255];
}

const canvasFactory = new NodeCanvasFactory();
const canvasAndCtx = canvasFactory.create(width, height);

// Fill white background first
const bg = canvasAndCtx.context._buf;
for (let i = 0; i < bg.length; i += 4) { bg[i] = 255; bg[i+1] = 255; bg[i+2] = 255; bg[i+3] = 255; }

console.log(`🖼️  Rendering page 1 (${width}×${height} @ ${scale}× scale)…`);
await page.render({
  canvasContext: canvasAndCtx.context,
  viewport,
  canvasFactory,
}).promise;

// Build a simple BMP buffer (Tesseract.js accepts BMP)
function buildBMP(rgbaBuf, w, h) {
  const rowBytes = w * 3;
  const paddedRow = (rowBytes + 3) & ~3;
  const imgSize = paddedRow * h;
  const fileSize = 54 + imgSize;
  const buf = Buffer.alloc(fileSize);
  // BMP header
  buf.write("BM", 0);
  buf.writeUInt32LE(fileSize, 2);
  buf.writeUInt32LE(54, 10); // pixel data offset
  // DIB header
  buf.writeUInt32LE(40, 14);
  buf.writeInt32LE(w, 18);
  buf.writeInt32LE(-h, 22); // top-down
  buf.writeUInt16LE(1, 26);  // planes
  buf.writeUInt16LE(24, 28); // bpp
  buf.writeUInt32LE(imgSize, 34);
  let off = 54;
  for (let y2 = 0; y2 < h; y2++) {
    for (let x2 = 0; x2 < w; x2++) {
      const src = (y2 * w + x2) * 4;
      buf[off++] = rgbaBuf[src + 2]; // B
      buf[off++] = rgbaBuf[src + 1]; // G
      buf[off++] = rgbaBuf[src];     // R
    }
    off += paddedRow - rowBytes; // padding
  }
  return buf;
}

const bmpBuf = buildBMP(canvasAndCtx.context._buf, width, height);

// ── Step 2: OCR with Tesseract.js ──────────────────────────────────
console.log("🔍 Running OCR (Tesseract.js – this may take a moment)…");
const worker = await createWorker("eng");
const { data: { text } } = await worker.recognize(bmpBuf);
await worker.terminate();

console.log(`✅ OCR complete — extracted ${text.length} characters.\n`);
console.log("── Extracted text (preview) ─────────────────────");
console.log(text.slice(0, 2000));
console.log("─────────────────────────────────────────────────\n");

// ── Step 3: Write to Excel ──────────────────────────────────────────
const workbook = new ExcelJS.Workbook();
const sheet = workbook.addWorksheet("OCR Output");

sheet.columns = [
  { header: "Line #", key: "line", width: 10 },
  { header: "Text", key: "text", width: 120 },
];

// Style the header row
sheet.getRow(1).font = { bold: true };

const lines = text.split("\n");
lines.forEach((line, i) => {
  sheet.addRow({ line: i + 1, text: line });
});

await workbook.xlsx.writeFile(xlsxPath);
console.log(`📊 Excel saved → ${xlsxPath}  (${lines.length} rows)`);

