    fillText() {}, strokeText() {},
    setLineDash() {}, getLineDash() { return []; },
    createImageData(w2, h2) { return { data: new Uint8ClampedArray(w2 * h2 * 4), width: w2, height: h2 }; },
    // Properties pdfjs sets:
    fillStyle: "#ffffff", strokeStyle: "#000000",
    lineWidth: 1, lineCap: "butt", lineJoin: "miter",
    miterLimit: 10, lineDashOffset: 0,
    font: "10px sans-serif", textAlign: "left", textBaseline: "alphabetic",
    globalAlpha: 1, globalCompositeOperation: "source-over",
    imageSmoothingEnabled: true, filter: "none",
  };
  return ctx;
}

function makeCanvas(w, h) {
  const buf = new Uint8ClampedArray(w * h * 4);
  const ctx = makeContext(buf, w, h);
  const canvas = {
    width: w, height: h,
    getContext() { return ctx; },
  };
  ctx.canvas = canvas;
  return { canvas, context: ctx };
}

class NodeCanvasFactory {
  create(w, h)               { return makeCanvas(w, h); }
  reset(pair, w, h)          { const n = makeCanvas(w, h); pair.canvas = n.canvas; pair.context = n.context; }
  destroy(_pair)             {}
}

